MagickBooleanType ReadPSDChannel(Image *image, const ImageInfo *image_info,
                                 const PSDInfo *psd_info, LayerInfo *layer_info,
                                 const size_t channel, const PSDCompressionType compression,
                                 ExceptionInfo *exception) {
  MagickBooleanType status = MagickTrue;
  size_t *sizes = (size_t *) AcquireQuantumMemory(1, sizeof(*sizes));
  if (sizes == (size_t *) NULL) {
    ThrowBinaryException(ResourceLimitError, "MemoryAllocationFailed", image->filename);
    return MagickFalse;
  }

  if (layer_info->mask && layer_info->mask->top == 0 && layer_info->mask->left == 0 &&
      layer_info->mask->width == image->columns && layer_info->mask->height == image->rows)
    layer_info->mask = (LayerInfo *) RelinquishMagickMemory(layer_info->mask);

  switch (compression) {
    case NoCompression:
      status = ReadPSDUncompressedChannel(image, image_info, psd_info, layer_info, channel, exception);
      break;
    case RLECompression:
      status = ReadPSDRLECompressedChannel(image, image_info, psd_info, layer_info, channel, exception);
      break;
    default:
      ThrowPSDException(OptionError, "UnsupportedCompressionType", image->filename);
      status = MagickFalse;
      break;
  }

  if (sizes != (size_t *) NULL)
    sizes = (size_t *) RelinquishMagickMemory(sizes);

  if (SeekBlob(image, (psd_info->channel_sizes_offset + (channel * sizeof(*sizes))), 0) == MagickFalse)
    status = MagickFalse;

  return status;
}

MagickBooleanType ReadPSDChannel(Image *image, const ImageInfo *image_info,
                                  const PSDInfo *psd_info, LayerInfo *layer_info,
                                  const size_t channel, PSDCompressionType compression,
                                  ExceptionInfo *exception) {
  MagickBooleanType status = MagickTrue;
  size_t length = 0;

  /* Check if mask is applicable */
  if (layer_info->has_mask[channel])
    if (!ReadPSDChannelData(image, image_info, psd_info, layer_info, channel, compression, exception))
      return MagickFalse;

  switch (compression) {
    case NoCompression:
      status = ReadNoCompressedChannelData(image, image_info, psd_info, layer_info, channel, exception);
      break;
    case RLECompression:
      status = ReadRLECompressedChannelData(image, image_info, psd_info, layer_info, channel, exception);
      break;
    default:
      (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
                                   "UnsupportedCompressionType", "`%d' is not a supported compression type", compression);
      status = MagickFalse;
      break;
  }

  if (status == MagickFalse)
    return status;

  /* Seek back to the appropriate position in the image blob */
  length = SeekBlob(image, (MagickSizeType) (psd_info->blob_offset + layer_info->offset[channel]), 0);

  if (length != (psd_info->blob_offset + layer_info->offset[channel])) {
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
                                 "UnableToSeekInImageBlob", "Failed to seek to channel data position");
    return MagickFalse;
  }

  return status;
}

MagickBooleanType ReadPSDChannel(Image *image, const ImageInfo *image_info,
                                 const PSDInfo *psd_info, LayerInfo *layer_info,
                                 const size_t channel, PSDCompressionType compression,
                                 ExceptionInfo *exception) {
  MagickBooleanType status = MagickTrue;
  size_t *sizes = NULL;
  MagickSizeType length;

  if ((psd_info->has_mask[channel] != 0) && (layer_info->channel_sizes[channel] > 0))
    (void) ReadBlobMSBLong(image, 4);  /* Skip mask size placeholder */

  if (layer_info->channel_sizes[channel] > 0) {
    size_t number_pixels = layer_info->channel_sizes[channel];
    if (number_pixels > (MagickMax(size_t)/2))
      ThrowPSDException(ResourceLimitError, "MemoryAllocationFailed", image);

    if ((compression == PSDNoCompression) || (compression == 0)) {
      status = ReadPSDChannelDataUncompressed(image, image_info, psd_info,
                                              layer_info, channel, compression, exception);
    }
    else if (compression == PSDRLECompression) {
      status = ReadPSDChannelDataRLE(image, image_info, psd_info,
                                     layer_info, channel, compression, exception);
    }
    else {
      (void) ThrowMagickException(exception, MagickFunction,
                                  CoderError, "UnsupportedPSDCompressionType", "%u",
                                  (unsigned int) compression);
      status = MagickFalse;
    }

    if (image->blob == (BlobInfo *) NULL)
      status = MagickFalse;

    if (image->blob->length != 0)
      (void) SeekBlob(image, -image->blob->length, SEEK_CUR);
  }

  if (sizes != NULL)
    sizes = (size_t *) RelinquishMagickMemory(sizes);

  return status;
}

MagickBooleanType ReadPSDChannel(Image *image, const ImageInfo *image_info, const PSDInfo *psd_info, LayerInfo *layer_info, const size_t channel, PSDCompressionType compression, ExceptionInfo *exception) {
  MagickBooleanType status = MagickTrue;
  size_t width = layer_info->width;
  size_t height = layer_info->height;
  MagickSizeType length;
  MagickOffsetType offset;

  if (layer_info->mask != (LayerMask *) NULL) {
    /* Handle mask applicability */
    (void) CopyMagickMemory(image->meta_data, layer_info->mask->data, layer_info->mask->length);
  }

  switch (compression) {
    case NoCompression:
      status = ReadPSDUncompressedChannel(image, image_info, psd_info, layer_info, channel, exception);
      break;
    case RLECompression:
      status = ReadPSDRLECompressedChannel(image, image_info, psd_info, layer_info, channel, exception);
      break;
    case ZIPCompression:
    case ZIPWithPrediction:
      status = ReadPSDZIPCompressedChannel(image, image_info, psd_info, layer_info, channel, compression, exception);
      break;
    default:
      (void) ThrowMagickException(exception, GetMagickModule(), CodingError, "UnsupportedPSDCompressionType", " ");
      return MagickFalse;
  }

  if (!status)
    return MagickFalse;

  length = width * height;
  offset = (MagickOffsetType) (TellBlob(image) - (MagickOffsetType) length);

  if (SeekBlob(image, offset, SEEK_SET) == -1)
    return MagickFalse;

  if (length != (MagickSizeType) (TellBlob(image) - offset))
    return MagickFalse;

  return MagickTrue;
}

MagickBooleanType ReadPSDChannel(Image *image, const ImageInfo *image_info,
                                 const PSDInfo *psd_info, LayerInfo *layer_info,
                                 const size_t channel, PSDCompressionType compression,
                                 ExceptionInfo *exception) {
  MagickBooleanType status = MagickTrue;
  size_t *sizes = (size_t *) AcquireQuantumMemory(1, sizeof(*sizes));
  if (sizes == (size_t *) NULL)
    ThrowBinaryException(ResourceLimitError, "MemoryAllocationFailed", image->filename);

  if (IsPSDMaskChannel(channel) != MagickFalse)
    status = ReadPSDLayerMask(image, image_info, psd_info, layer_info, channel, compression, exception);
  else
    switch (compression) {
      case NoCompression:
        status = ReadUncompressedPSDChannel(image, image_info, psd_info, layer_info, channel, sizes, exception);
        break;
      case RLECompression:
        status = ReadRLECompressedPSDChannel(image, image_info, psd_info, layer_info, channel, sizes, exception);
        break;
      case ZIPCompression:
        status = ReadZIPCompressedPSDChannel(image, image_info, psd_info, layer_info, channel, sizes, exception);
        break;
      case DEFLATECompression:
        status = ReadDEFLATECompressedPSDChannel(image, image_info, psd_info, layer_info, channel, sizes, exception);
        break;
      default:
        ThrowXException(exception, "UnsupportedPSDCompressionType", "ChannelReadingFailed");
        status = MagickFalse;
    }

  if (sizes != (size_t *) NULL)
    RelinquishMagickMemory(sizes);

  if (status == MagickFalse)
    return MagickFalse;

  (void) SeekBlob(image, (MagickOffsetType) (layer_info->offset[channel]), SEEK_SET);
  return MagickTrue;
}
